@Component
struct RestoreView {
  @State retryAllowed: boolean = false
  @State notice: string = ''
  enableCapacityRecovery(): void {
    this.retryAllowed = true
    this.notice = 'capacity recovery available'
  }
  build() {
    Button('Restore capacity').onClick(() => this.enableCapacityRecovery())
    Text(this.notice)
  }
}

